package io.github.jhipster.sample.service;

import io.github.jhipster.sample.domain.Operation;
import io.github.jhipster.sample.repository.OperationRepository;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Service for reading {@link Operation} entities by business criteria.
 */
@Service
@Transactional(readOnly = true)
public class OperationService {

    private static final Logger LOG = LoggerFactory.getLogger(OperationService.class);

    static final Duration RECENT_WINDOW = Duration.ofDays(30);

    private final OperationRepository operationRepository;

    private final Clock clock;

    public OperationService(OperationRepository operationRepository, Clock clock) {
        this.operationRepository = operationRepository;
        this.clock = clock;
    }

    /**
     * Get the operations dated within the last 30 days.
     *
     * @param pageable the pagination information.
     * @return the page of recent operations.
     */
    public Page<Operation> findRecent(Pageable pageable) {
        Instant now = Instant.now(clock);
        LOG.debug("Request to get Operations between {} and {}", now.minus(RECENT_WINDOW), now);
        return operationRepository.findRecentWithEagerRelationships(now.minus(RECENT_WINDOW), now, pageable);
    }
}
